-- 접속사 since/though Step 2 — 100문항 (객관식)
-- template_topic: 접속사 since/though
-- category: problem, mode: interactive

DO $$
DECLARE
  q jsonb;
  a jsonb;
BEGIN
  DELETE FROM naesin_templates WHERE title = E'접속사 since/though Step 2';

  q := jsonb_build_array(
    -- ============================================================
    -- Part 1: 빈칸 채우기 (Q1–Q8)
    -- ============================================================
    jsonb_build_object('number',1,
      'question',E'[Part 1] 빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\n__________ everyone played well, we lost the game.',
      'options',jsonb_build_array(E'As if',E'Because',E'Unless',E'Although',E'Since'),
      'answer',E'4',
      'explanation',E'Although — 양보: ~에도 불구하고. 모두가 잘 했음에도 졌다는 양보의 의미.'),
    jsonb_build_object('number',2,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\n__________ it was too dark for him to go back to town, he stayed there.',
      'options',jsonb_build_array(E'Although',E'Since',E'Unless',E'Even if',E'While'),
      'answer',E'2',
      'explanation',E'Since — 이유: ~때문에. 너무 어두워서 마을로 돌아갈 수 없었기 때문에 그곳에 머물렀다.'),
    jsonb_build_object('number',3,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nOur car wouldn''t start, so we were late.\n= __________ our car wouldn''t start, we were late.',
      'options',jsonb_build_array(E'If',E'When',E'Since',E'Before',E'Though'),
      'answer',E'3',
      'explanation',E'Since — 이유: so(그래서)를 사용한 원인-결과 문장을 since(~때문에)로 바꿔 쓸 수 있다.'),
    jsonb_build_object('number',4,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\n__________ the wind was blowing hard, it wasn''t very cold.',
      'options',jsonb_build_array(E'As if',E'Because',E'Since',E'Although',E'Unless'),
      'answer',E'4',
      'explanation',E'Although — 양보: 바람이 세게 불었지만 그다지 춥지 않았다. 예상과 반대되는 결과이므로 양보 접속사가 적절하다.'),
    jsonb_build_object('number',5,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nA: Did you go to bed early last night?\nB: I stayed up late __________ I was very exhausted.',
      'options',jsonb_build_array(E'despite',E'unless',E'since',E'because',E'although'),
      'answer',E'5',
      'explanation',E'although — 양보: 매우 지쳤음에도 불구하고 늦게까지 깨어 있었다.'),
    jsonb_build_object('number',6,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nA: What did Rachel do last weekend?\nB: She went hiking __________ it was snowy and chilly.',
      'options',jsonb_build_array(E'because',E'unless',E'since',E'although',E'if'),
      'answer',E'4',
      'explanation',E'although — 양보: 눈이 오고 추웠음에도 불구하고 등산을 갔다.'),
    jsonb_build_object('number',7,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nWe can''t be together, but I will always love you.\n= __________ we can''t be together, I will always love you.',
      'options',jsonb_build_array(E'Even',E'Since',E'Although',E'With',E'Because'),
      'answer',E'3',
      'explanation',E'Although — 양보: but(하지만)을 사용한 대조 문장을 Although(~에도 불구하고)로 바꿔 쓸 수 있다.'),
    jsonb_build_object('number',8,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nWe had a lot of snow last week, so the streets were still slippery.\n= __________ we had a lot of snow last week, the streets were still slippery.',
      'options',jsonb_build_array(E'If',E'When',E'Although',E'Since',E'While'),
      'answer',E'4',
      'explanation',E'Since — 이유: so(그래서)를 사용한 원인-결과 문장을 Since(~때문에)로 바꿔 쓸 수 있다.'),

    -- ============================================================
    -- Part 2: (A)와 (B) 빈칸 + 모두고르기 (Q9–Q24)
    -- ============================================================
    jsonb_build_object('number',9,
      'question',E'[Part 2] (A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A)__________ the weather is so bad, I''m not going out today.\n(B)__________ it was raining, we continued playing soccer.',
      'options',jsonb_build_array(E'(A) Since — (B) While',E'(A) Although — (B) Because',E'(A) Though — (B) Though',E'(A) Since — (B) Even though',E'(A) Because — (B) Although'),
      'answer',E'4',
      'explanation',E'(A) Since — 이유: 날씨가 나쁘기 때문에 나가지 않겠다.\n(B) Even though — 양보: 비가 왔음에도 축구를 계속했다.'),
    jsonb_build_object('number',10,
      'question',E'__________ he had a terrible car accident, he wasn''t hurt at all.\n\n※ 적절하지 않은 것을 모두 고르시오. (정답 2개)',
      'options',jsonb_build_array(E'Since',E'Though',E'Although',E'Even though',E'Until'),
      'answer',E'1,5',
      'explanation',E'Since(이유: ~때문에)와 Until(~까지)은 양보 문맥에 부적절하다. 끔찍한 교통사고를 당했지만 전혀 다치지 않았다는 양보의 의미이므로 Though, Although, Even though가 적절하다.'),
    jsonb_build_object('number',11,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nThough he got up late, __________.',
      'options',jsonb_build_array(E'he couldn''t have breakfast',E'he didn''t do his homework',E'he wasn''t late for class',E'he missed the bus',E'he couldn''t take his lunch box'),
      'answer',E'3',
      'explanation',E'Though(양보) — 늦게 일어났지만 수업에 늦지 않았다. 양보절의 내용과 반대되는 결과가 와야 한다.'),
    jsonb_build_object('number',12,
      'question',E'빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nAlthough the traffic was heavy, __________.',
      'options',jsonb_build_array(E'we arrived on time',E'we were very late',E'we missed the class',E'we were late for school',E'I was too late to be on time'),
      'answer',E'1',
      'explanation',E'Although(양보) — 교통이 막혔지만 제시간에 도착했다. 양보절의 내용과 반대되는 결과가 와야 한다.'),
    jsonb_build_object('number',13,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) Her voice was shaking (A)__________ all her efforts to control it.\n(B) (B)__________ Betty left me 20 years ago, I still miss her.',
      'options',jsonb_build_array(E'(A) despite — (B) Since',E'(A) although — (B) But',E'(A) since — (B) Though',E'(A) although — (B) In spite of',E'(A) despite — (B) Though'),
      'answer',E'5',
      'explanation',E'(A) despite + 명사구: 목소리를 조절하려는 모든 노력에도 불구하고 떨리고 있었다.\n(B) Though + 절: Betty가 20년 전에 떠났지만 여전히 그리워한다.'),
    jsonb_build_object('number',14,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) __________ the wind blew hard, the old man went out to the sea to fish.\n(B) She ran the race (B)__________ an injury.',
      'options',jsonb_build_array(E'(A) Although — (B) despite',E'(A) Since — (B) because of',E'(A) Although — (B) because of',E'(A) Since — (B) despite',E'(A) Though — (B) in spite'),
      'answer',E'1',
      'explanation',E'(A) Although + 절: 바람이 세게 불었지만 낚시하러 바다로 나갔다 (양보).\n(B) despite + 명사: 부상에도 불구하고 경주에 참가했다 (양보). in spite는 단독으로 쓸 수 없고 in spite of가 되어야 한다.'),
    jsonb_build_object('number',15,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) Sarah''s been sick (A)__________ Friday.\n(B) He never gave up his dream (B)__________ his illness.',
      'options',jsonb_build_array(E'(A) since — (B) though',E'(A) since — (B) despite',E'(A) because of — (B) despite',E'(A) because of — (B) though',E'(A) since — (B) because of'),
      'answer',E'2',
      'explanation',E'(A) since + 시점: 금요일부터 아팠다 (시간의 since).\n(B) despite + 명사: 병에도 불구하고 꿈을 포기하지 않았다 (양보).'),
    jsonb_build_object('number',16,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) I''m tired (A)__________ I went to bed late at night.\n(B) (B)__________ his wealth, he is not happy.',
      'options',jsonb_build_array(E'(A) although — (B) Despite',E'(A) since — (B) Although',E'(A) since — (B) In spite of',E'(A) although — (B) In spite of',E'(A) because of — (B) Despite'),
      'answer',E'3',
      'explanation',E'(A) since + 절: 밤에 늦게 잤기 때문에 피곤하다 (이유).\n(B) In spite of + 명사: 그의 부에도 불구하고 행복하지 않다 (양보).'),
    jsonb_build_object('number',17,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) __________ it is small, the apartment is very expensive.\n(B) (B)__________ all our efforts, the event was a failure.',
      'options',jsonb_build_array(E'(A) Since — (B) Although',E'(A) Although — (B) Despite',E'(A) Despite — (B) Even though',E'(A) Because — (B) Despite',E'(A) Although — (B) Since'),
      'answer',E'2',
      'explanation',E'(A) Although + 절: 작지만 아파트가 매우 비싸다 (양보).\n(B) Despite + 명사구: 모든 노력에도 불구하고 행사는 실패였다 (양보).'),
    jsonb_build_object('number',18,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) The situation has changed (A)__________ I left.\n(B) Cathy hasn''t phoned (B)__________ she went to Berlin.',
      'options',jsonb_build_array(E'(A) because — (B) although',E'(A) since — (B) although',E'(A) although — (B) since',E'(A) since — (B) since',E'(A) because — (B) since'),
      'answer',E'4',
      'explanation',E'(A) since + 과거 시점: 내가 떠난 이후로 상황이 변했다 (시간).\n(B) since + 과거 시점: Cathy는 베를린에 간 이후로 전화하지 않았다 (시간).'),
    jsonb_build_object('number',19,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) The baseball match was cancelled (A)__________ the heavy rain.\n(B) (B)__________ her careful spending, Carrie has saved 3,000 dollars.',
      'options',jsonb_build_array(E'(A) since — (B) Despite',E'(A) although — (B) Because of',E'(A) because of — (B) Because of',E'(A) because of — (B) Despite',E'(A) despite — (B) Because of'),
      'answer',E'3',
      'explanation',E'(A) because of + 명사: 폭우 때문에 야구 경기가 취소되었다 (이유).\n(B) Because of + 명사: 신중한 지출 덕분에 Carrie는 3,000달러를 모았다 (이유).'),
    jsonb_build_object('number',20,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) We''re still very good friends (A)__________ we rarely see each other.\n(B) It has been raining (B)__________ last night.',
      'options',jsonb_build_array(E'(A) since — (B) since',E'(A) although — (B) because of',E'(A) although — (B) since',E'(A) since — (B) because of',E'(A) because — (B) since'),
      'answer',E'3',
      'explanation',E'(A) although + 절: 서로 거의 만나지 못하지만 여전히 좋은 친구이다 (양보).\n(B) since + 시점: 어젯밤부터 비가 내리고 있다 (시간).'),
    jsonb_build_object('number',21,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) __________ she had no qualifications, she got the job.\n(B) Everybody likes her (B)__________ the kindness she showed us.',
      'options',jsonb_build_array(E'(A) Since — (B) because of',E'(A) Despite — (B) since',E'(A) Even though — (B) because of',E'(A) Because of — (B) although',E'(A) Although — (B) despite'),
      'answer',E'3',
      'explanation',E'(A) Even though + 절: 자격이 없었음에도 취직했다 (양보).\n(B) because of + 명사구: 그녀가 보여준 친절 때문에 모두 좋아한다 (이유).'),
    jsonb_build_object('number',22,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) __________ he was good at painting, he could easily learn how to draw cartoons.\n(B) (B)__________ the bad weather caused by a terrible storm, the plane changed its course.',
      'options',jsonb_build_array(E'(A) Although — (B) Despite',E'(A) Since — (B) Although',E'(A) Though — (B) Since',E'(A) Since — (B) Because of',E'(A) Although — (B) Because of'),
      'answer',E'4',
      'explanation',E'(A) Since + 절: 그림을 잘 그렸기 때문에 만화 그리기를 쉽게 배울 수 있었다 (이유).\n(B) Because of + 명사구: 폭풍으로 인한 나쁜 날씨 때문에 비행기가 항로를 변경했다 (이유).'),
    jsonb_build_object('number',23,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) He refused to attend the seminar (A)__________ they asked him many times.\n(B) (B)__________ being late for school, she could still take the exam.',
      'options',jsonb_build_array(E'(A) while — (B) For',E'(A) while — (B) Although',E'(A) although — (B) To',E'(A) although — (B) In spite of',E'(A) since — (B) For'),
      'answer',E'4',
      'explanation',E'(A) although + 절: 여러 번 요청했음에도 세미나 참석을 거부했다 (양보).\n(B) In spite of + 동명사: 학교에 늦었음에도 불구하고 시험을 볼 수 있었다 (양보).'),
    jsonb_build_object('number',24,
      'question',E'(A)와 (B)에 들어갈 말로 가장 적절한 것을 고르시오.\n\n(A) At first you thought it would be warm because the sun was shining, but when you went outside, it wasn''t warm at all.\n→ (A)__________ the sun was shining, it wasn''t very warm.\n(B) He was in love with her (B)__________ he did not put that name to his feeling.',
      'options',jsonb_build_array(E'(A) Although — (B) although',E'(A) As long as — (B) although',E'(A) Because — (B) as long as',E'(A) Although — (B) because',E'(A) So — (B) as long as'),
      'answer',E'1',
      'explanation',E'(A) Although + 절: 해가 비추었지만 따뜻하지 않았다 (양보).\n(B) although + 절: 그 감정에 이름을 붙이지 않았지만 사랑에 빠져 있었다 (양보).'),

    -- ============================================================
    -- Part 3: since 의미 구별 (Q25–Q34)
    -- ============================================================
    jsonb_build_object('number',25,
      'question',E'[Part 3] 밑줄 친 since의 의미가 나머지 넷과 다른 것을 고르시오.\n\n① <u>Since</u> it was Friday, I stayed up late.\n② I haven''t heard from him <u>since</u> last year.\n③ <u>Since</u> I had a bad cold, I stayed at home all day.\n④ <u>Since</u> I''m very tired, I''m going to go to bed right away.\n⑤ We don''t have to go to school <u>since</u> tomorrow is a holiday.',
      'options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),
      'answer',E'2',
      'explanation',E'②의 since는 시간(~이후로): 작년 이후로 연락이 없다. 나머지 ①③④⑤는 모두 이유(~때문에)의 since이다.'),
    jsonb_build_object('number',26,
      'question',E'밑줄 친 since의 의미가 나머지 넷과 다른 것을 고르시오.\n\n① Take your umbrella <u>since</u> it''s raining outside.\n② Mike didn''t come to school <u>since</u> he had a cold.\n③ You should cook dinner <u>since</u> you''re a good cook.\n④ He has been sick <u>since</u> he graduated from university.\n⑤ I couldn''t buy the book <u>since</u> I used up my allowance.',
      'options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),
      'answer',E'4',
      'explanation',E'④의 since는 시간(~이후로): 대학을 졸업한 이후로 아프다. 나머지 ①②③⑤는 모두 이유(~때문에)의 since이다.'),
    jsonb_build_object('number',27,
      'question',E'밑줄 친 since의 의미가 나머지 넷과 다른 것을 고르시오.\n\n① <u>Since</u> Jane came home late, her dad was worried about her.\n② I was waiting inside the café <u>since</u> it was very cold outside.\n③ <u>Since</u> Judy is kind, everyone likes her.\n④ It has been a couple of years <u>since</u> she left me.\n⑤ He couldn''t buy a car <u>since</u> he didn''t have enough money.',
      'options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),
      'answer',E'4',
      'explanation',E'④의 since는 시간(~이후로): 그녀가 떠난 지 몇 년이 되었다. 나머지 ①②③⑤는 모두 이유(~때문에)의 since이다.'),
    jsonb_build_object('number',28,
      'question',E'밑줄 친 since의 의미가 나머지 넷과 다른 것을 고르시오.\n\n① I have known her <u>since</u> I was young.\n② Lisa wants to be a scientist <u>since</u> she''s good at science.\n③ <u>Since</u> he bought her a gift, she was happy.\n④ We have lived in Seoul <u>since</u> we left our hometown.\n⑤ <u>Since</u> I''ve just started learning Chinese, I can''t speak it well.',
      'options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),
      'answer',E'1',
      'explanation',E'①의 since는 시간(~이후로): 어렸을 때부터 그녀를 알고 있다 (have known + since). 나머지 ②③⑤는 이유(~때문에)의 since이다.'),
    jsonb_build_object('number',29,
      'question',E'다음 중 밑줄 친 since의 의미가 같은 것끼리 묶인 것은?\n\nⓐ Minho was absent today <u>since</u> he was sick.\nⓑ Sujin will help me <u>since</u> she is my best friend.\nⓒ I have studied English <u>since</u> I was ten years old.\nⓓ He likes this town <u>since</u> people are very polite and kind.\nⓔ She has lived in Seoul <u>since</u> she was nineteen.',
      'options',jsonb_build_array(E'ⓐ, ⓑ',E'ⓐ, ⓒ',E'ⓑ, ⓓ',E'ⓐ, ⓑ, ⓓ',E'ⓒ, ⓓ, ⓔ'),
      'answer',E'4',
